        for (int i = 0; i < n; i++) {
            sum += fibonacci(i);
        }

        System.out.println("Sum of all Fibonacci numbers: " + sum);
    }

    public static int fibonacci(int n) {
        if (n <= 1) {
            return n;
        } else {
            return fibonacci(n - 1) + fibonacci(n - 2);
        }
    }
