#include <iostream>

// Recursive function to add two numbers 
int addRecursive(int a, int b) 
{ 
    // If b is 0, we return a 
    if (b == 0) 
        return a; 

    // Get sum of a and b without carry 
    int sum = a ^ b; 

    // Get carry of a and b 
    int carry = (a & b) << 1; 

    // Add the two numbers 
    return addRecursive(sum, carry); 
} 

// Driver function 
int main() 
{ 
    int a = 5, b = 3;
    std::cout << a << " + " << b << " = " << addRecursive(a, b); 
    return 0; 
}
