```java
public static void insertionSort(int[] array) {
    for (int i = 1; i < array.length; i++) {
        int temp = array[i];
        int j = i - 1;

        while (j >= 0 && array[j] > temp) {
            array[j + 1] = array[j];
            j--;
        }

        array[j + 1] = temp;
    }
}

int[] array = {8, 5, 6, 7, 1, 2};
insertionSort(array);
for (int item: array) {
    System.out.print(item + " ");
}
