    } else {
        printSpaces((2 * (n - 1)) + 1);
        printStars((2 * (5 - n)) + 1);
        std::cout << std::endl;
        printDiamond(n - 1, false);
        printSpaces((2 * (n - 1)) + 1);
        printStars((2 * (5 - n)) + 1);
    }
}

