```java
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class ArmstrongNumbers {

    public static void main(String[] args) {
        // Prompt the user to enter the starting and ending numbers
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the starting number: ");
        int start = scanner.nextInt();
        System.out.print("Enter the ending number: ");
        int end = scanner.nextInt();

        // Find Armstrong numbers within the range
        List<Integer> armstrongNumbers = findArmstrongNumbers(start, end);

        // Display the Armstrong numbers in ascending order
        System.out.println("Armstrong numbers within the range " + start + " to " + end + ":");
        for (int number : armstrongNumbers) {
            System.out.println(number);
        }
    }

    public static List<Integer> findArmstrongNumbers(int start, int end) {
        List<Integer> armstrongNumbers = new ArrayList<>();

        for (int number = start; number <= end; number++) {
            int sum = 0;
            int temp = number;
            int digits = countDigits(number);

            while (temp != 0) {
                int remainder = temp % 10;
                sum += Math.pow(remainder, digits);
                temp /= 10;
            }

            if (sum == number) {
                armstrongNumbers.add(number);
            }
        }

        Collections.sort(armstrongNumbers);
        return armstrongNumbers;
    }

    public static int countDigits(int number) {
        int count = 0;
        while (number != 0) {
            number /= 10;
            count++;
        }
        return count;
    }
}
```

This program uses a separate method `findArmstrongNumbers()` to encapsulate the logic for finding Armstrong numbers within a given range. The `countDigits()` method is used to calculate the number of digits in a given number.

