    std::cout << "f1 - f2: " << (f1 - f2) << std::endl;
    std::cout << "f1 * f2: " << (f1 * f2) << std::endl;
    std::cout << "f1 / f2: " << (f1 / f2) << std::endl;

    return 0;
}
```

