# Step 8:  Define a function to check if all substrings in the set are used
def is_all_used(used):
    for val in used.values():
        if val != True:
            return False
    return True

# Step 9:  Define a function to check if the substrings form a circle using depth-first search
def is_circle(d, pre):
    used = {x: False for x in d}
    pre_none = [x for x in used if x not in pre]
    s_arr = []
    for x in pre_none:
        cur = []
        flg = dfs(x, d, used, cur)
        if flg == True:
            return (True, None)
        s_arr.append(cur)
    if is_all_used(used) != True:
        return (True, None)
    return (False, s_arr)

# Step 10:  Define a depth-first search function to check for circles in the substrings
def dfs(u, d, used, cur):
    used[u] = True
    cur.append(u)
    flg = False
    for v in d[u]:
        if used[v] == True:
            return True
        flg = dfs(v, d, used, cur)
        if flg == True:
            return flg
    return flg

# Step 11:  Define a function to add substrings to the graph
def push(d, u, v=None):
    if u not in d:
        d[u] = set()
    if v is not None:
        if v not in d:
            d[v] = set()
        d[u].add(v)

# Step 12:  Define a function to count the occurrences of each substring
def push_p(d, v):
    if v not in d:
        d[v] = 0
    d[v] += 1

# Step 13:  Define a function to check if the degree of the graph is valid
def is_deg_valid(d):
    for u in d:
        if len(d[u]) > 1:
            return True
    return False

# Step 14:  Define the main function to solve the problem based on the input and return the non-empty good string with the minimum length
def solve():
    n = int(input())
    # Step 15:  Initialize an empty graph
    d = {}  
    # Step 16:  Initialize an empty dictionary for storing substrings
    pre = {}  
    for _ in range(n):
        s = input()
        if len(s) == 1:
            # Step 17:  Add single letter substrings to the graph
            push(d, s)  
        else:
            for (u, v) in zip(s[:-1], s[1:]):
                # Step 18:  Add substrings to the graph
                push(d, u, v)  
                # Step 19:  Count the occurrences of each substring
                push_p(pre, v)  
    # Step 20:  Check if a circle of substrings exists
    (flg, arr) = is_circle(d, pre)  
    # Step 21:  Check if the degree of the graph is valid or if a circle exists
    if is_deg_valid(d) or flg == True:  
        # Step 22:  Return "NO" if no good string exists
        return 'NO'  
    # Step 23:  Consolidate the substrings
    S = [''.join(x) for x in arr]  
    # Step 24:  Sort the substrings lexicographically
    S = sorted(S)  
    # Step 25:  Return the lexicographically minimum good string
    return ''.join([s for s in S])  
print(solve())

