```python
def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def nth_prime(n):
    count = 0
    number = 2
    while count < n:
        if is_prime(number):
            count += 1
            if count == n:
                return number
        number += 1
    return -1

