To implement the GCD calculation using bitwise operations, you can modify the `gcd` function as follows:

```c
int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    if (a == 0) {
        return b;
    }
    if (a == b) {
        return a;
    }
    if ((a & 1) == 0) {
        if ((b & 1) == 1) {
            return gcd(a >> 1, b);
        } else {
            return gcd(a >> 1, b >> 1) << 1;
        }
    }
    if ((b & 1) == 0) {
        return gcd(a, b >> 1);
    }
    if (a > b) {
        return gcd((a - b) >> 1, b);
    }
    return gcd((b - a) >> 1, a);
